import"./chunk-2NFLSA4Y.js";var r={transformer:{theory:{concept:"[[A transformer is a device that raises or lowers an alternating voltage without changing its frequency; it works by electromagnetic induction.]] It has two windings on a common iron core."},section:{how:{title:"How a transformer works",text:"Alternating current in the primary winding continually changes the magnetic field in the iron core. This changing field passes through the secondary winding and induces a voltage there. The core guides the magnetic field around both windings."},ratio:{title:"The turns ratio",text:"[[For an ideal transformer, the ratio of secondary voltage to primary voltage equals the ratio of their turns.]] More turns on the secondary make a step-up transformer; fewer turns make a step-down transformer. Try changing either winding and watch the output voltage."},power:{title:"Voltage and current",text:"[[An ideal transformer transfers power: when voltage goes up, current goes down by a corresponding amount.]] Real transformers lose some energy, so the output power is a little less than the input power."},dc:{title:"Why direct current does not work",text:"[[A transformer needs a changing magnetic field.]] Direct current becomes steady after it is switched on, so it induces no continuing voltage in the secondary. A steady DC supply can also drive excessive current in the primary and overheat the transformer."},losses:{title:"Real transformers and losses",text:"Real windings have electrical resistance, so part of the energy heats the copper (I\xB2\xB7R). The iron core also loses a little energy every cycle through eddy currents and magnetic hysteresis; real cores are made of thin insulated steel sheets to reduce this. This model includes the winding resistance and the magnetizing current, but not the core losses, so real efficiencies are slightly lower. Large power transformers still reach about 99 %."},grid:{title:"Transformers in the power grid",text:"Power stations use step-up transformers to raise voltage for long-distance transmission. For the same power, a higher voltage means a smaller current and less heating in the wires. Step-down transformers then lower the voltage for homes and devices."},history:{title:"From induction to the power grid",text:"In 1831 Michael Faraday wound two coils on one iron ring and saw a current in the second coil only when he switched the first one on or off \u2014 the first transformer. In 1885 the Hungarian engineers Zipernowsky, Bl\xE1thy and D\xE9ri built efficient closed-core transformers in Budapest, and in 1886 William Stanley used them for an AC lighting network in the USA. Since then high-voltage transmission has relied on transformers; today the highest-voltage AC power lines run at about 1000 kV."},check:{title:"Check your understanding",text:"What happens to the output voltage if the secondary has twice as many turns as the primary? (It is about twice as high.) Why does a transformer need alternating current? (It needs a changing magnetic field.) What happens to current when voltage is stepped up in an ideal transformer? (It decreases so power is conserved.) Try these ideas by changing the controls."}},formula:{ratio:"Ideal transformer voltage and turns ratio",currents:"Ideal transformer current ratio",power:"Input power is approximately output power",induction:"Induced voltage from changing magnetic flux",efficiency:"Efficiency: useful output power divided by input power",field:"Peak magnetic field in the core"},variable:{voltages:"Primary and secondary voltages",currents:"Primary and secondary currents",turns:"Number of turns in each winding",flux:"Magnetic flux",field:"Magnetic field",area:"Cross-sectional area of the core",omega:"Angular frequency of the supply"},assumption:{core:"The magnetic field is treated as uniform across the core. It is linear up to a sharp saturation limit; leakage flux, eddy currents and hysteresis are ignored.",windings:"Each winding is represented by its total number of turns and a single resistance. Resistance follows R = k\xB7N\xB2 for a fixed copper window; detailed geometry and heating are ignored.",slow:"The animation is 100 times slower than reality. The displayed steady AC readings use the unsaturated sinusoidal model; detailed transient effects are not included.",rms:"Displayed AC voltages and currents are RMS values; the instantaneous waveforms are sinusoidal."},param:{voltage:"Supply voltage",primaryTurns:"Primary turns",secondaryTurns:"Secondary turns",supply:"Supply type",load:"Load resistance",timeStep:"Time step"},hint:{voltage:"The RMS voltage applied to the primary winding.",primaryTurns:"The primary winding receives the supply voltage.",secondaryTurns:"The turns ratio controls the secondary voltage.",supply:"A transformer needs a changing supply to induce a secondary voltage.",load:"The connected device is represented by a resistance.",timeStep:"A smaller time step resolves the AC waveform more finely."},preset:{v12:"12 V",mains:"Mains (230 V)",down20:"Step down \xD720",same:"Same voltage",up2:"Step up \xD72"},supply:{ac:"Alternating current (AC)",dc:"Direct current (DC)"},measure:{u2:"Secondary RMS voltage",ratio:"Turns ratio N\u2082/N\u2081",idealU2:"Ideal secondary voltage",i1:"Primary RMS current",i2:"Secondary RMS current",powerIn:"Input power",powerOut:"Output power",efficiency:"Efficiency",peakField:"Peak core field",magnetizing:"Magnetizing current"},graph:{voltages:"Primary and secondary voltage",u1:"Primary voltage u\u2081",u2:"Secondary voltage u\u2082",currents:"Primary and secondary current",i1:"Primary current i\u2081",i2:"Secondary current i\u2082"},view:{fluxOption:"Magnetic flux in the core",primary:"Primary \xB7 {turns} turns",secondary:"Secondary \xB7 {turns} turns",field:"Core field B = {value}",ac:"AC \xB7 {voltage}",dc:"DC \xB7 {voltage}",lamp:"Load \xB7 {load} \xB7 {power}",ratio:"N\u2082/N\u2081 = {ratio}",dcNote:"DC: no changing field, no output",saturated:"Core saturated"},challenge:{charger:{title:"Make a 5 V supply",description:"Use the 230 V supply to produce about 5 V at the secondary.",hint:"Choose far fewer turns in the secondary than in the primary."},stepUp:{title:"Step the voltage up",description:"Produce at least 400 V from a supply no higher than 230 V.",hint:"Give the secondary more turns than the primary."},same:{title:"Keep the voltage the same",description:"Make the secondary voltage approximately equal to the supply voltage.",hint:"Use the same number of turns in both windings."},dc:{title:"Try direct current",description:"Set a DC supply of at least 100 V and observe the secondary output.",hint:"A steady magnetic field does not induce a continuing voltage."},bright:{title:"Light the load",description:"Deliver at least 50 W to the load without saturating the core.",hint:"Use AC and adjust the turns ratio and load."},efficient:{title:"Make it efficient",description:"Reach at least 98% efficiency and deliver at least 30 W without saturating the core.",hint:"Keep the core below saturation and choose a suitable load."},saturate:{title:"Saturate the core",description:"Use AC and adjust the settings until the core saturates.",hint:"A stronger magnetic field can be produced with more voltage or fewer primary turns."}}}},a={sim:r};export{a as default,r as sim};
